const closePosts = [];
const closeEngine = createEngine({ refreshMs: 0, quietMs: 60000, minDwellMs: 0 }, makeHost(closePosts));
const closeTarget = session('session-close');
closeEngine.accept(closeTarget, event('turn/start', { turn: 1 }));
closeEngine.accept(closeTarget, toolCall('bash', { ball_doing: '正在收尾' }, 'close-1'));
await closeEngine.pending();
await closeEngine.tick();

check('心跳重发当前那句，不换文案', () => {
    assert.equal(closePosts.at(-1).text, '正在收尾');
    assert.equal(closePosts.filter((post) => post.text === '正在收尾').length, 2, '应为 1 条状态 + 1 条心跳');
});

closeEngine.accept(closeTarget, event('turn/end', { turn: 1, reason: { kind: 'completed' } }));
await closeEngine.tick();
check('turn 结束：done（带最后一句）→ 4 秒后 idle，之后不再有任何推送', async () => {
    assert.equal(closePosts.at(-1).phase, 'done');
    assert.equal(closePosts.at(-1).ball_doing, '正在收尾');
    closeEngine.sessions.get(closeTarget).idleAt = Date.now() - 1;
    await closeEngine.tick();
    await closeEngine.pending();
    assert.equal(closePosts.at(-1).phase, 'idle');
    assert.equal(closePosts.at(-1).ball_doing, '');
    const afterIdle = closePosts.length;
    await closeEngine.tick();
    await closeEngine.pending();
    await closeEngine.tick();
    await closeEngine.pending();
    assert.equal(closePosts.length, afterIdle, 'idle 之后不许再有推送');
    assert.equal(closeEngine.state.displayed, null);
});

