    plainEngine.accept(plain, toolResult('plain-1'));
    plainEngine.accept(plain, event('assistant/message', { turn: 1, step: 2, message: { role: 'assistant', content: [{ type: 'text', text: '普通会话的收尾话' }] } }));
    plainEngine.accept(plain, event('turn/end', { turn: 1, reason: { kind: 'completed' } }));
    await plainEngine.tick();
