/* ================================================================== live === */

if (LIVE) {
    console.log('\n=== LIVE：真实悬浮球（不调用任何模型）===');
    if (!process.env.DSH_ANDROID_BRIDGE_URL) throw new Error('没有 DSH_ANDROID_BRIDGE_URL，live 模式需要真机控制桥');
    const liveLog = path.join(root, 'live.jsonl');
    const live = makeCtx();
    apply(live.ctx, { logFile: liveLog, refreshMs: 18000 });

    // A real slice of a real session record, replayed as-is. These calls predate
    // the schema change, so they exercise the fallback path.
    const files = fs.readdirSync(sessionsRoot, { withFileTypes: true })
        .filter((entry) => entry.isDirectory())
        .flatMap((workspace) => fs.readdirSync(path.join(sessionsRoot, workspace.name), { withFileTypes: true })
            .filter((entry) => entry.isDirectory())
            .map((entry) => path.join(sessionsRoot, workspace.name, entry.name, 'session.v4.jsonl.zstd')))
        .filter((file) => fs.existsSync(file))
        .map((file) => ({ file, mtime: fs.statSync(file).mtimeMs }))
        .sort((left, right) => right.mtime - left.mtime);
    const source = files.find((entry) => !replayWindow(entry.file, 1).session?.origin) ?? files[0];
    const replay = replayWindow(source.file, 3);
    console.log(`  真实会话：${source.file}`);
    console.log(`  回放事件：${replay.events.map((item) => item.type).join(' → ')}`);
    const liveSession = session(replay.session?.id ?? 'live-session', {
        cwd: replay.session?.cwd,
        origin: replay.session?.origin,
        delegationDepth: replay.session?.delegationDepth ?? 0,
    });
    live.emit('session/created', liveSession);
    for (const item of replay.events) live.emit('session/event', liveSession, item);

    // And one call carrying the field, exactly as the extended schema will make
    // the model send it.
    live.emit('session/event', liveSession, event('step/start', { turn: 1, step: 99 }));
    live.emit('session/event', liveSession, toolCall('bash', { command: 'echo hi', ball_doing: '正在把实时状态接到悬浮球' }, 'live-1'));

    // The deployed plugin is running in the harness at the same time and writes
    // the same ball, so the line can be replaced a moment later by real work.
    // Poll instead of reading once: seeing it at all is the proof.
    let ballState = '';
    let seen = false;
    const deadline = Date.now() + 3000;
    while (Date.now() < deadline) {
        const status = await fetch(`${process.env.DSH_ANDROID_BRIDGE_URL}/ball/state`, {
            headers: { 'X-Dsh-Token': process.env.DSH_ANDROID_BRIDGE_TOKEN },
        });
        ballState = await status.text();
        if (ballState.includes('正在把实时状态接到悬浮球')) {
            seen = true;
            break;
        }
        await sleep(120);
    }

    const liveEntries = entries(liveLog);
    for (const entry of liveEntries.filter((item) => item.ev === 'push')) {
        console.log(`  push  ${String(entry.phase).padEnd(5)} ${String(entry.note).padEnd(11)} ${entry.text}`);
    }
    console.log(`  球上看到这句话：${seen ? '是' : '否'}；最后读到的 /ball/state：${ballState}`);
    const ops = liveEntries.filter((entry) => entry.ev === 'op');
    console.log(`  工具调用 ${ops.length} 次 → 推送 ${liveEntries.filter((entry) => entry.ev === 'push').length} 条，模型调用 0 次`);
    check('live：真实工具调用 → 真实悬浮球上出现 ball_doing，全程 0 次模型调用', () => {
        assert.ok(ops.length >= 1, '没有回放到工具调用');
        assert.ok(liveEntries.every((entry) => !String(entry.ev).startsWith('llm')));
        assert.ok(seen, `球上应出现过那个 ball_doing，最后读到：${ballState}`);
    });
}

